def resolve_function(name_or_alias: str):
    """Return a function record by semantic name or historical alias."""
    address = FUNCTION_ALIASES.get(name_or_alias)
    if address is None:
        return None
    return {"address": address, **FUNCTION_SYMBOLS[address]}
